WITH metrics AS (SELECT id, customer_id, browser, started_at, country, LAST_VALUE(browser, TRUE) OVER (PARTITION BY TO_DATE(started_at), country ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, LAST_VALUE(country) IGNORE NULLS OVER w_hist AS last_known_country, FIRST_VALUE(country) IGNORE NULLS OVER w_running AS first_known_country, LAST_VALUE(browser) IGNORE NULLS OVER w_hist AS last_known_browser_2, ROW_NUMBER() OVER (PARTITION BY browser, device ORDER BY started_at DESC, id) AS seq_no FROM sessions WINDOW w_hist AS (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)) SELECT s.id, s.customer_id, s.browser, s.started_at, s.country, s.last_known_browser_2, s.seq_no, CASE WHEN country RLIKE '^(DE|TH)$' THEN 'PRIORITY' WHEN country RLIKE '^(US|SG)$' THEN 'OTHER_ZONE' ELSE 'CORE' END AS country_zone, (SELECT MIN(t2.amount) FROM orders t2 WHERE t2.customer_id = s.customer_id) AS min_order_amount FROM metrics s ORDER BY min_order_amount
